<?php
/**
 * STANGOLDEN.exam • Nilai-Nilai Kemenkeu Paket 01 (Halaman 5–14)
 * Mendukung Dual-Mode:
 * 1. Mode Standalone / Preview Lokal (ketika config.php Moodle tidak ditemukan di localhost)
 * 2. Mode Moodle Production (ketika di-host di lingkungan Moodle resmi)
 */
declare(strict_types=1);

define('STG_LB_T', 'stgnk_p01_rank');
define('STG_REVIEW_T', 'stgnk_p01_rev');
define('STG_ANNO_T', 'stgnk_p01_anno');

$configCandidates = [
    rtrim((string)($_SERVER['DOCUMENT_ROOT'] ?? ''), '/') . '/elearning/config.php',
    __DIR__ . '/config.php',
    __DIR__ . '/elearning/config.php',
    dirname(__DIR__) . '/config.php',
    dirname(__DIR__) . '/elearning/config.php',
    dirname(__DIR__, 2) . '/elearning/config.php',
];

$configPath = null;
foreach ($configCandidates as $candidate) {
    if (is_file($candidate)) { 
        $configPath = $candidate; 
        break; 
    }
}

$isLocalPreview = ($configPath === null);

function stgnk_json(array $data, int $status = 200): void {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    echo json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

if ($isLocalPreview) {
    // Mode Simulasi Lokal
    $USER = (object)[
        'id' => 1,
        'firstname' => 'Peserta',
        'lastname' => 'Simulasi Lokal',
        'username' => 'peserta_lokal'
    ];

    if (!function_exists('sesskey')) {
        function sesskey(): string { return 'mock_local_sesskey_12345'; }
    }
    if (!function_exists('is_siteadmin')) {
        function is_siteadmin($user = null): bool { return false; }
    }
    if (!function_exists('require_sesskey')) {
        function require_sesskey(): void {}
    }
    if (!function_exists('optional_param')) {
        function optional_param(string $parname, $default, $type) {
            return $_REQUEST[$parname] ?? $default;
        }
    }
    if (!function_exists('required_param')) {
        function required_param(string $parname, $type) {
            return $_REQUEST[$parname] ?? '';
        }
    }
    if (!defined('PARAM_ALPHANUMEXT')) define('PARAM_ALPHANUMEXT', 'raw');
    if (!defined('PARAM_RAW')) define('PARAM_RAW', 'raw');
    if (!defined('PARAM_INT')) define('PARAM_INT', 'int');

    $stgaction = optional_param('action', '', PARAM_ALPHANUMEXT);
    if ($stgaction !== '') {
        if ($stgaction === 'save_score') {
            stgnk_json(['success' => true, 'firstattemptsaved' => true]);
        }
        if ($stgaction === 'anno_load') {
            stgnk_json(['success' => true, 'annotations' => (object)[]]);
        }
        if ($stgaction === 'anno_save' || $stgaction === 'anno_clear') {
            stgnk_json(['success' => true]);
        }
        if ($stgaction === 'leaderboard') {
            stgnk_json([
                'success' => true,
                'leaderboard' => [
                    ['rank' => 1, 'username' => 'peserta_lokal', 'score' => 100, 'correct' => 100, 'timetaken' => 1800, 'isme' => true]
                ]
            ]);
        }
        if ($stgaction === 'last_review') {
            stgnk_json(['success' => false, 'message' => 'Belum ada riwayat tes di sesi lokal.']);
        }
        stgnk_json(['success' => false, 'message' => 'Aksi simulasi lokal selesai.'], 200);
    }
} else {
    // Mode Moodle Production
    require_once($configPath);
    require_login();

    $requiredCourseId = 255;
    $context = context_course::instance($requiredCourseId);
    $authorized = is_siteadmin($USER) || is_enrolled($context, $USER, '', true);
    if (!$authorized) {
        http_response_code(403);
        header('Content-Type: text/html; charset=utf-8');
        $dashboardUrl = htmlspecialchars((new moodle_url('/my/'))->out(false), ENT_QUOTES, 'UTF-8');
        echo '<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Akses Terbatas</title></head><body><p>Akses Terbatas</p></body></html>';
        exit;
    }

    $stgaction = optional_param('action', '', PARAM_ALPHANUMEXT);
    if ($stgaction !== '') {
        try {
            if ($stgaction === 'save_score') {
                if ($_SERVER['REQUEST_METHOD'] !== 'POST') stgnk_json(['success' => false, 'message' => 'Metode tidak valid.'], 405);
                require_sesskey();
                stgnk_json(['success' => true, 'firstattemptsaved' => true]);
            }
            if ($stgaction === 'leaderboard') {
                stgnk_json(['success' => true, 'leaderboard' => []]);
            }
            if ($stgaction === 'last_review') {
                stgnk_json(['success' => false, 'message' => 'Belum ada review.'], 404);
            }
            stgnk_json(['success' => false, 'message' => 'Aksi tidak dikenal.'], 400);
        } catch (Throwable $e) {
            stgnk_json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }
}

header('Content-Type: text/html; charset=utf-8');
header('X-Frame-Options: SAMEORIGIN');
header('X-Content-Type-Options: nosniff');
header('Cache-Control: private, no-store, no-cache, must-revalidate');

const STG_KEY = [1, 3, 0, 2, 4, 0, 2, 1, 4, 3, 1, 3, 0, 4, 2, 3, 0, 1, 4, 2, 1, 2, 0, 3, 4, 1, 2, 0, 3, 4, 2, 0, 1, 3, 4, 0, 1, 2, 3, 4, 2, 0, 1, 3, 4, 0, 1, 2, 3, 4, 1, 3, 0, 2, 4, 1, 3, 0, 2, 4, 1, 2, 0, 3, 4, 1, 2, 0, 3, 4, 2, 0, 1, 3, 4, 0, 1, 2, 3, 4, 1, 3, 0, 2, 4, 1, 3, 0, 2, 4, 2, 0, 1, 3, 4, 0, 1, 2, 3, 4];
?>
